"""Swagger contract for the independent traces service."""
AUTH = [{'adminBearer':[]}]
RESEARCH_AUTH = [{'researchBearer':[]}]
READ = {'responses':{'200':{'description':'Successful JSON result'},'401':{'description':'Wrong or missing role credential'},
                     '400':{'description':'Invalid filter or pagination'},'404':{'description':'Not found'},
                     '503':{'description':'ClickHouse unavailable or content checksum mismatch'}}}
RESEARCH = {'responses':{'200':{'description':'Content-free or bounded research result'},
                         '400':{'description':'Invalid revision, cursor or page size'},
                         '401':{'description':'Dedicated research bearer required'},
                         '404':{'description':'Released revision not found'},
                         '409':{'description':'Hold: revision not released, invalid detector output or release gate failed'},
                         '503':{'description':'ClickHouse unavailable'}}}
SPECIFICATION = {'openapi':'3.1.0','info':{'title':'Copilot Traces','version':'0.0.1',
    'description':('Independent detailed log and tool-content investigation for upskilling and future warehouse assessment. '
                   'The admin role can inspect raw evidence and publish a curated revision; the '
                   'separate research role can only read a released, sanitised revision through bounded JSONL/gzip exports. '
                   'Exact returned records do not prove complete conversation coverage. Research output is pseudonymised, '
                   'not guaranteed anonymous; real-world privacy evaluation and release approval remain pending.')},
    'servers':[{'url':'/'}], 'components':{'securitySchemes':{
        'adminBearer':{'type':'http','scheme':'bearer','description':'COPILOT_ADMIN_API_KEY: private log/content review, collection and manual release'},
        'statusBearer':{'type':'http','scheme':'bearer','description':'COPILOT_STATS_API_KEY: storage/health counts only'},
        'researchBearer':{'type':'http','scheme':'bearer','description':'COPILOT_RESEARCH_API_KEY: released curated research exports/schema/manifest only'},
        'otlpBearer':{'type':'http','scheme':'bearer','description':'Private .otlp-token: OTLP ingestion only'}}},
    'paths':{
        '/healthz':{'get':{'summary':'Live database readiness','responses':{'200':{'description':'Database responds'},'503':{'description':'Database unavailable'}}}},
        '/v1/copilot/storage':{'get':{**READ,'security':[{'statusBearer':[]}],'summary':'Storage counts, client signal counts and polling checkpoint'}},
        '/v1/review/records':{'get':{**READ,'security':AUTH,'summary':'Paginated record metadata without bodies',
            'parameters':[{'name':name,'in':'query','schema':schema} for name,schema in (
                ('after',{'type':'integer','minimum':0,'default':0}),('limit',{'type':'integer','minimum':1,'maximum':100,'default':25}),
                ('request_id',{'type':'string'}),('order',{'type':'string','enum':['asc','desc'],'default':'asc'}))]}},
        '/v1/review/records/{record_id}':{'get':{**READ,'security':AUTH,'summary':'Original record with complete body string and checksum',
            'description':'Keeps request/response content, tool arguments/results, headers and other fields exactly as returned by the Enterprise API. A gateway request ID correlates an exchange; it is not necessarily a conversation ID.',
            'parameters':[{'name':'record_id','in':'path','required':True,'schema':{'type':'string','pattern':'^[a-f0-9]{64}$'}}]}},
        '/v1/review/client-batches':{'get':{**READ,'security':AUTH,'summary':'Newest 100 client OTLP batch metadata rows'}},
        '/v1/review/client-batches/{batch_id}':{'get':{**READ,'security':AUTH,'summary':'Complete client OTLP JSON batch, including full captured tool attributes',
            'parameters':[{'name':'batch_id','in':'path','required':True,'schema':{'type':'string','pattern':'^[a-f0-9]{64}$'}}]}},
        '/v1/collection/jobs':{'get':{**READ,'security':AUTH,'summary':'Newest 50 collection jobs'},
            'post':{'security':AUTH,'summary':'Queue one serial Enterprise collection or readiness refresh',
                'requestBody':{'required':True,'content':{'application/json':{'schema':{'type':'object','additionalProperties':False,'required':['kind'],
                    'properties':{'kind':{'type':'string','enum':['records','refresh']}}},'example':{'kind':'records'}}}},
                'responses':{'202':{'description':'Queued'},'400':{'description':'Invalid kind'},'401':{'description':'Admin credential required'},
                             '409':{'description':'Existing job is active'},'503':{'description':'Database unavailable'}}}},
        '/v1/ingest/records':{'post':{'security':AUTH,'summary':'Import a bounded authorised Enterprise record array directly into ClickHouse',
            'requestBody':{'required':True,'content':{'application/json':{'schema':{'type':'array','minItems':1,'maxItems':1000,'items':{'type':'object'}}}}},
            'responses':{'200':{'description':'Durable insert acknowledged; stable event IDs deduplicate overlap'},'400':{'description':'Invalid or conflicting records'},'401':{'description':'Admin credential required'},'503':{'description':'Database unavailable'}}}},
        '/v1/research/status':{'get':{**READ,'security':AUTH,'summary':'Admin-only derivation, release-gate and retention status',
            'description':'Never returns prompts, tool content, record IDs or policy aliases. The research bearer cannot call this route. '
                          'Counts of a deriving or resetting revision are live dispositions; finalised revisions report stored counts.'}},
        '/v1/research/revisions':{'post':{'security':AUTH,'summary':'Snapshot current raw records into a new versioned curated revision',
            'description':'Deterministic revision identity includes schema/parser/policy/detector versions, a frozen source membership ledger and its content digest. Bounded pages derive only ledger members. This does not publish anything.',
            'requestBody':{'required':True,'content':{'application/json':{'schema':{'type':'object','additionalProperties':False},'example':{}}}},
            'responses':{'201':{'description':'Revision created or returned'},'400':{'description':'Invalid snapshot request'},
                         '401':{'description':'Admin credential required'},'409':{'description':'Policy/key/detector unavailable; derivation held'},
                         '503':{'description':'Database unavailable'}}}},
        '/v1/research/releases':{'post':{'security':AUTH,'summary':'Manually release one completed curated revision',
            'description':('Fail-closed. Requires the restricted policy and pseudonym key, explicit manual raw and curated retention, '
                           'an evaluated release setting, one terminal disposition per frozen source member, no pending/retry/failed work, '
                           'matching source/event checksums and acknowledge_review=true. Held records are excluded and enumerated per observation.'),
            'requestBody':{'required':True,'content':{'application/json':{'schema':{'type':'object','additionalProperties':False,
                'required':['revision_id','acknowledge_review'],'properties':{'revision_id':{'type':'string','pattern':'^rev_[a-f0-9]{16,64}$'},
                'acknowledge_review':{'type':'boolean'}}},'example':{'revision_id':'rev_REPLACE','acknowledge_review':True}}}},
            'responses':{'201':{'description':'Released and immutable content-free manifest created'},'400':{'description':'Invalid release request'},
                         '401':{'description':'Admin credential required'},'404':{'description':'Revision not found'},
                         '409':{'description':'HOLD: release gate, retention, detector, processing or review check failed'},
                         '503':{'description':'Database unavailable'}}}},
        '/v1/research/review/taxonomy':{'get':{**READ,'security':AUTH,'summary':'Code-owned annotation taxonomy (admin)',
            'description':'Dimensions, closed label sets and evidence requirements for annotation-taxonomy/1. Content-free.'}},
        '/v1/research/review/summary':{'get':{**READ,'security':AUTH,'summary':'Revision hold, gap, excluded/unsupported/held and annotation counts (admin)',
            'description':'Aggregates only: observation dispositions by failure class, current-pipeline events by kind and coverage, release blockers and known gaps. No prompts, tool content or source IDs.',
            'parameters':[{'name':'revision','in':'query','required':True,'schema':{'type':'string','pattern':'^rev_[a-f0-9]{16,64}$'}}]}},
        '/v1/research/review/observations':{'get':{**READ,'security':AUTH,'summary':'Bounded observation dispositions for one revision (admin)',
            'description':'Keyset pages ordered by observation_ref, maximum 100 per page. Content-free; no record IDs.',
            'parameters':[{'name':'revision','in':'query','required':True,'schema':{'type':'string','pattern':'^rev_[a-f0-9]{16,64}$'}},
                          {'name':'after','in':'query','schema':{'type':'string','pattern':'^obs_[a-f0-9]{16,64}$'}},
                          {'name':'limit','in':'query','schema':{'type':'integer','minimum':1,'maximum':100,'default':50}},
                          {'name':'status','in':'query','schema':{'type':'string','enum':['pending','processed','held','retry_pending','retry_exhausted','failed']}}]}},
        '/v1/research/review/compare':{'get':{**READ,'security':AUTH,'summary':'Bounded original/derived comparison for one explicitly selected observation (admin)',
            'description':'Returns the checksum-verified restricted original (omitted above 256 KiB, with its exact admin-only record_id) beside at most 100 derived events within a 256 KiB display budget, plus current annotations. A single event over the budget is not loaded and is named in omitted_events. Resume derived events with from=next_from_index, which always advances. Neither side establishes a complete conversation.',
            'parameters':[{'name':'revision','in':'query','required':True,'schema':{'type':'string','pattern':'^rev_[a-f0-9]{16,64}$'}},
                          {'name':'observation','in':'query','required':True,'schema':{'type':'string','pattern':'^obs_[a-f0-9]{16,64}$'}},
                          {'name':'from','in':'query','schema':{'type':'integer','minimum':0,'default':0}}]}},
        '/v1/research/review/annotations':{'get':{**READ,'security':AUTH,'summary':'Current and recent operator annotations for one observation (admin)',
            'description':'Restricted sidecar, never part of a research export. Dimensions without a record are reported as unreviewed.',
            'parameters':[{'name':'revision','in':'query','required':True,'schema':{'type':'string','pattern':'^rev_[a-f0-9]{16,64}$'}},
                          {'name':'observation','in':'query','required':True,'schema':{'type':'string','pattern':'^obs_[a-f0-9]{16,64}$'}}]},
            'post':{'security':AUTH,'summary':'Append one operator-reviewed annotation citing supporting events (admin)',
                'description':'Append-only; raw records, derived events and released bytes are untouched. A label other than unknown must cite current events of the observation that satisfy the dimension and label evidence rule (for example tool_success_observed needs a cited tool result, assistant_reported_done an assistant message); tool names alone are not intent. reviewer is an operator-asserted label, not an authenticated identity. note is restricted free text (500 characters), returned only to admin and never exported.',
                'requestBody':{'required':True,'content':{'application/json':{'schema':{'type':'object','additionalProperties':False,
                    'required':['revision_id','observation_ref','dimension','label','evidence_event_ids','reviewer'],
                    'properties':{'revision_id':{'type':'string','pattern':'^rev_[a-f0-9]{16,64}$'},
                                  'observation_ref':{'type':'string','pattern':'^obs_[a-f0-9]{16,64}$'},
                                  'dimension':{'type':'string','enum':['task_intent','context_retrieval','orchestration','outcome']},
                                  'label':{'type':'string'},
                                  'evidence_event_ids':{'type':'array','maxItems':20,'items':{'type':'string','pattern':'^event_[a-f0-9]{16,64}$'}},
                                  'reviewer':{'type':'string','pattern':'^[A-Za-z0-9._-]{1,64}$'},
                                  'note':{'type':'string','maxLength':500}}}}}},
                'responses':{'201':{'description':'Annotation stored or identical latest annotation returned'},'400':{'description':'Invalid label, evidence or fields'},
                             '401':{'description':'Admin credential required'},'404':{'description':'Revision or observation not found'},
                             '503':{'description':'Database unavailable'}}}},
        '/v1/research/schema':{'get':{**RESEARCH,'security':RESEARCH_AUTH,'summary':'JSON Schema for one research event',
            'description':'Content-free. Each JSONL line is one event matching this schema. Payload fields are sanitised typed nested objects, not re-encoded JSON strings.'}},
        '/v1/research/manifest':{'get':{**RESEARCH,'security':RESEARCH_AUTH,'summary':'Content-free manifest for a released revision',
            'description':'Contains schema/parser/policy/detector versions, disposition and event counts, per-observation mapped/withheld/unsupported coverage, source-frame counts and the sanitised export checksum. Contains no original IDs, raw-content hashes or identity mappings.',
            'parameters':[{'name':'revision','in':'query','required':True,'schema':{'type':'string','pattern':'^rev_[a-f0-9]{16,64}$'}}]}},
        '/v1/research/export/pages':{'get':{**RESEARCH,'security':RESEARCH_AUTH,'summary':'Bounded JSON export page with explicit resume cursor',
            'description':'Deterministically ordered by observed source sequence, event index and scoped event ID. The revision is pinned by every cursor. page_sha256 covers UTF-8 JSONL bytes for this page. complete=true and manifest_sha256 are returned only when this page actually reaches the end.',
            'parameters':[{'name':'revision','in':'query','required':True,'schema':{'type':'string','pattern':'^rev_[a-f0-9]{16,64}$'}},
                          {'name':'cursor','in':'query','schema':{'type':'string'}},
                          {'name':'limit','in':'query','schema':{'type':'integer','minimum':1,'maximum':500,'default':500}}]}},
        '/v1/research/export':{'get':{**RESEARCH,'security':RESEARCH_AUTH,'summary':'Bounded UTF-8 JSONL research export, optional gzip',
            'description':('One typed event per physical line; newlines inside strings are escaped. Bounded by limit (maximum 500). '
                           'X-Research-Complete is true only when the final page is actually returned; X-Research-Manifest-SHA256 is absent on partial pages. '
                           'A transport interruption therefore cannot look complete. gzip=1 returns deterministic application/gzip bytes.'),
            'parameters':[{'name':'revision','in':'query','required':True,'schema':{'type':'string','pattern':'^rev_[a-f0-9]{16,64}$'}},
                          {'name':'cursor','in':'query','schema':{'type':'string'}},
                          {'name':'limit','in':'query','schema':{'type':'integer','minimum':1,'maximum':500,'default':500}},
                          {'name':'gzip','in':'query','schema':{'type':'string','enum':['0','1'],'default':'0'}}],
            'responses':{'200':{'description':'Bounded JSONL or gzip page','headers':{
                'X-Research-Revision':{'schema':{'type':'string'}},'X-Research-Page-SHA256':{'schema':{'type':'string'}},
                'X-Research-Complete':{'schema':{'type':'string','enum':['true','false']}},'X-Research-Next-Cursor':{'schema':{'type':'string'}},
                'X-Research-Manifest-SHA256':{'schema':{'type':'string'}}},
                'content':{'application/x-ndjson':{'schema':{'type':'string'}},'application/gzip':{'schema':{'type':'string','contentMediaType':'application/gzip'}}}},
                '400':{'description':'Invalid revision, cursor or page size'},'401':{'description':'Dedicated research bearer required'},
                '404':{'description':'Released revision not found'},'409':{'description':'Revision is on HOLD'},'503':{'description':'ClickHouse unavailable'}}}},
    }}
for signal,key in (('traces','resourceSpans'),('logs','resourceLogs'),('metrics','resourceMetrics')):
    SPECIFICATION['paths']['/v1/'+signal]={'post':{'security':[{'otlpBearer':[]}],
        'summary':'Persist complete OTLP JSON '+signal+' batch (internal collector destination)',
        'description':'64 MiB bound, no truncation or content transform. Public gRPC/HTTP protobuf is accepted by the separate standard OTLP collector. OTLP is not derived into the research dataset; the manifest reports that coverage gap.',
        'requestBody':{'required':True,'content':{'application/json':{'schema':{'type':'object','required':[key],'properties':{key:{'type':'array','items':{'type':'object'}}}}}}},
        'responses':{'200':{'description':'Database acknowledged'},'400':{'description':'Invalid JSON'},'401':{'description':'OTLP token required'},'503':{'description':'Database unavailable'}}}}
